    desc: '你获得一只为你服务的魔宠，魔宠精魄可以采用你选择的动物形态之一：蝙蝠、猫、青蛙、鹰、蜥蜴、章鱼、猫头鹰、老鼠、渡鸦、蜘蛛、鼬，或其他挑战等级为0的野兽。魔宠出现在施法距离内一处未被占据的空间，拥有所选生物的数据，但生物种类为天族、妖精或邪魔，由你选择。魔宠可独立行动，但会遵循你的命令。\n\n心灵连接：魔宠距你100尺内期间，你可以与其心灵交流。你还可以用附赠动作将自己的视觉和听觉切换到魔宠的感官，持续至你下一回合开始，并同时享有魔宠自身的特殊感官。施展触碰法术时，魔宠可以在距你100尺内用反应帮你传递该法术。\n\n战斗：魔宠是你和盟友的盟友。战斗时它为自己掷先攻并在自己回合行动。魔宠无法攻击，但能正常执行其他动作。\n\n魔宠的消失：魔宠生命值降至0时会消失，并在你再次施展此法术后重新出现。你可以用魔法动作暂时解散魔宠送入一个口袋位面，也可以永久解散它。暂时解散时，你可以用魔法动作使其重新出现于距你30尺内任意未占空间中。魔宠归0或进入口袋位面时，会将穿着或携带的物品留在原空间。\n\n独一无二：你同一时间不能拥有多于一只魔宠。如果你已拥有魔宠期间施展此法术，作为替代，你会使其采用一个新的符合条件的形态。',
