    desc: '你点名或描述一个你熟悉的生物。只要该生物与你相距不超过1000尺，你就会感测到该生物的方位。如果该生物正在移动，则你也将知晓其移动方向。\n\n该法术可以定位一个你认识的特定生物；或者定位特定一类生物中距你最近个体，不过你需要在30尺内看到过该类生物至少一次。如果目标并不处于原本形态，例如受变形术或石化术影响，则无法定位。\n\n任意厚度的铅阻挡你与被定位生物之间的通路时，该生物无法被此法术定位。',
