    desc: '你在施法距离内指定一处你能看见且未被占据的空间，创造出一只由魔法能量组成、闪烁微光的大型手掌。这只手会在持续时间内存在，并听从命令移动，模仿你自己手掌的各类动作。\n\n这只手是一个物件，AC为20，生命值等于你的最大生命值。若其生命值降至0，法术提前终止。它不会占据其所处空间。\n\n施展此法术时，你可以令巨手移动至多60尺并造成下列效应之一。你也可以在随后的回合以附赠动作再造成下列效应之一。\n\n金刚拳：巨手对自身周围5尺范围内的目标发动一次近战法术攻击，命中造成5d8力场伤害。\n\n飞击掌：巨手尝试推撞自身周围5尺范围内一个体型不超过巨型的生物。目标进行力量豁免，失败则被推动至多5+你施法属性调整值五倍尺，巨手随目标移动并保持5尺内。\n\n擒拿掌：巨手尝试擒抱自身周围5尺范围内一个体型不超过巨型的生物。目标进行敏捷豁免，失败则陷入受擒状态，逃脱DC等于你的法术豁免DC。巨手擒抱目标期间，你可以用附赠动作命令巨手挤压，造成4d6+你的施法属性调整值钝击伤害。\n\n护身掌：当攻击或效应以巨手空间为源点，或需要穿过巨手空间时，你获得半身掩护。此外，巨手所处空间对你的敌人视作困难地形。\n\n升环施法效应：使用高于五环法术位时，法术位每比五环高一环，金刚拳伤害提高2d8，擒拿掌伤害提高2d6。',
