    desc: '一面坚硬的非魔法石墙出现在施法距离内你指定的一点。石墙厚6寸，由十个10×10尺方板块组成，每块板块必须和至少一块其他板块相连。你也可以选择以十个10×20尺板块组成石墙，但厚度只有3寸。\n\n若石墙形成时穿过某生物所占空间，该生物会被推到石墙一侧，由你决定。若生物即将被石墙完全包围，则可进行一次敏捷豁免，成功时以反应按正常速度移动，避免被围住。\n\n你可以将石墙塑成想要的形状，但不能与其他生物或物件同占空间。它不必垂直地面，也不需要地基，但必须从稳固既有石块中延伸出来。若跨度超过20尺，必须把每块大小减半以创造支撑。你可以粗略塑形，造出城垛等。\n\n石墙是可受伤害的石制物件。每块板块AC 15，每寸厚有30生命值，免疫毒素和心灵伤害。当板块生命值降至0时被摧毁，相连板块也可能崩塌，由DM判断。\n\n如果你在整个法术持续时间内一直保持专注，则石墙永久存在且不能被解除；否则石墙在法术终止时消失。',
