    desc: '你围绕施法距离内一处指定地点以力场构筑出固定的立方状隐形监牢。你可以选择笼状或盒状。\n\n笼状监牢为各边长至多20尺的立方体，墙体由1/2寸粗的力场栅栏杆组成，每根杆子相距1/2寸。盒状监牢为各边长至多10尺的立方体，由力场墙密封，阻隔一切物质进出，也会阻挡从区域内向外或从外界向区域内施展的法术。\n\n施法时，所有完全在法术区域内的生物被困住。部分处于区域内或体型比区域更大的生物被从区域中心向外推开，直到完全离开区域。\n\n牢笼内生物不能以非魔法手段离开。若试图使用传送或跨位面旅行离开，必须先进行魅力豁免；成功则可离开，失败则无法离开并浪费该法术或效应。牢笼延伸至以太位面，屏蔽途经以太位面的旅行。该法术不能被解除魔法解除。',
