    desc: '由光构成的闪光多彩平面形成垂直而不透光的墙壁。墙至多长90尺、高30尺、厚1寸，并以施法距离内你能看见的一点为源点。你也可以将其塑成直径至多30尺的球体。若指定生成空间有生物占据，法术立即结束且无效。\n\n法墙发出100尺明亮光照和额外100尺微光光照。你和施法时指定的生物可以穿过法墙或停留在附近而不受伤害。其他能看见法墙的生物移动到距墙20尺内或在该处开始回合时，必须进行体质豁免，失败则目盲1分钟。\n\n法墙由七层组成。生物试图进入或穿过法墙时，逐层穿过所有光层，每穿过一层就进行敏捷豁免，失败则受对应光层影响。法墙AC 10，可以被摧毁，但必须按红到紫的顺序逐层以特定方式摧毁。光层被摧毁后在法术持续时间内保持被摧毁。反魔法场无法影响法墙，解除魔法只对紫墙有效。\n\n红：失败受12d6火焰伤害，成功半伤；非魔法远程攻击无法穿过，此层受25点寒冷伤害后摧毁。橙：失败受12d6强酸伤害；魔法远程攻击无法穿过，强风摧毁。黄：失败受12d6闪电伤害；受60点力场伤害后摧毁。绿：失败受12d6毒素伤害；被穿墙术或同等/更高环阶开口效应摧毁。蓝：失败受12d6寒冷伤害；受25点火焰伤害后摧毁。靛：失败后束缚，并在每回合结束进行体质豁免，累计三次成功则结束，累计三次失败则石化；法术无法穿过，被昼明术明亮光照摧毁。紫：失败后目盲，并在你下个回合开始时进行感知豁免，失败则被传送至DM选择的另一个位面；此层可被解除魔法摧毁。',
