export const spells = spellLists.flatMap(list => list.spells)

export function findSpellById(id) {
  return spells.find(spell => spell.id === id) ?? null
}

export function findSpellByBaseId(baseId) {
  return spells.find(spell => spell.baseId === baseId) ?? null
}

export function getSpellListById(listId) {
  return spellLists.find(list => list.id === listId) ?? null
}

export function getSpellsByList(listId) {
  return getSpellListById(listId)?.spells ?? []
}

export function getSpellsByLevel(listId, level) {
  return getSpellsByList(listId).filter(spell => spell.level === level)
}

export function getSpellsForClass(classId) {
  const list = spellLists.find(item => item.classId === classId)
  return list?.spells ?? []
}

export function searchSpells(listId, query, options = {}) {
  const q = String(query ?? '').trim().toLowerCase()
  const level = options.level
  const pool = listId ? getSpellsByList(listId) : spells
  const leveled = Number.isFinite(Number(level))
    ? pool.filter(spell => spell.level === Number(level))
    : pool

  if (!q) return leveled

  return leveled.filter(spell => {
    const haystack = [
      spell.name,
      spell.nameEn,
      spell.school,
      String(spell.level),
      ...(spell.special ?? []),
    ]
      .filter(Boolean)
      .join(' ')
      .toLowerCase()

    return haystack.includes(q)
  })
}
